{"script":"toml = repo.read("Cargo.toml")
src_list = repo.list("src")
files = {}
for f in src_list:
    if f.endswith("/"):
        sub = repo.list("src/" + f)
        for g in sub:
            files["src/" + f + g] = repo.read("src/" + f + g)
    else:
        files["src/" + f] = repo.read("src/" + f)
return {"Cargo.toml": toml, "files": files}
"}

